def intl(code):
    t = (TPL / f"deski_tlumaczenie_{code}.md").read_text(encoding="utf-8")
    blk = re.search(r"```\n(.*?)\n```", t, re.S).group(1)
    return blk.strip().split("\n\n")[-1]


def main():
    for code, d in L.items():
        for k in ("core", "pool"):
            for x in d[k]:
                assert len(x) <= 20, (code, x, len(x))
        assert len(d["titles"]) == 6 and len(d["A"]) == 5 and len(d["B"]) == 3 and len(d["C"]) == 3 and len(d["core"]) == 5 and len(d["pool"]) == 17, code
        for tt in d["titles"]:
            assert len(tt.replace("{B}", "Basset Griffon Vendéen Kurzhaar")) <= 140, (code, tt)
        h = d["hd"]
        fixed = (f"{h[0]}\n" + "\n".join(d["detail"]) + f"\n\n{h[1]}\n" + "\n".join(d["care"]) + f"\n\n{h[2]}\n" + "\n".join(d["where"]) + f"\n\n{h[3]}\n{d['why']}\n\n" + intl(code))
        md = [f"# Tłumaczenie ({d['name']}): popiersia wiszące \"Hanging Statue\" (79 ofert; szkic Claude'a, bez weryfikacji osoby natywnej, 03.11.2026)", "",
              "Status: EN zatwierdzony przez właścicielkę 03.11.2026. `{B}` = nazwa rasy z Rasy.xlsx dla tego języka. Wymiary: `{H} {W} {D}` w cm, `{H_IN} {W_IN} {D_IN}` w calach (liczby per oferta, przecinek dziesiętny wg języka). "
              + (f"Forma zwracania się: {d['form']}." if code != "pl" else "Polski sprawdza właścicielka."), "",
              "## Tytuł (6 wzorców)"] + [f"{i}. {x}" for i, x in enumerate(d["titles"], 1)] + ["", "## Pierwszy akapit: banki", "**A**"] + [f"- A{i}: {x}" for i, x in enumerate(d["A"], 1)] \
             + ["", "**B**"] + [f"- B{i}: {x}" for i, x in enumerate(d["B"], 1)] + ["", "**C**"] + [f"- C{i}: {x}" for i, x in enumerate(d["C"], 1)] \
             + ["", "## Sekcje stałe", "```", fixed, "```", "", "## Tagi (max 20 znaków, długości policzone skryptem)",
                "**Stałe:** " + ", ".join(f"{x} ({len(x)})" for x in d["core"]), "**Pula:** " + ", ".join(f"{x} ({len(x)})" for x in d["pool"]), ""]
        (TPL / f"hanging_tlumaczenie_{code}.md").write_text("\n".join(md), encoding="utf-8")
        print(code, "ok")


if __name__ == "__main__":
    main()
